// Multi-window complex object using BroadcastChannel
// VFX / particle-based "Vortex Field Ring" visuals.

// ---------- Cross-window state ----------

let channel = null;
let myId = null;

// id -> { id, x, y, w, h, lastSeen }
let peers = new Map();

let infoDiv;
let openBtn;

// ---------- Visual parameters ----------

const PARTICLE_COUNT = 900;
const FIELD_LINE_COUNT = 18;
const INNER_NOISE_SCALE = 0.9;
const OUTER_NOISE_SCALE = 1.6;

// ---------- Helpers for IDs & self state ----------

function makeId() {
  if (crypto && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return Math.random().toString(36).slice(2);
}

function updateSelfPeer() {
  if (!myId) return;
  peers.set(myId, {
    id: myId,
    x: window.screenX || 0,
    y: window.screenY || 0,
    w: window.innerWidth || windowWidth,
    h: window.innerHeight || windowHeight,
    lastSeen: Date.now()
  });
}

// ---------- BroadcastChannel wiring ----------

function connectChannel() {
  if (!("BroadcastChannel" in window)) {
    infoDiv.html(
      "BroadcastChannel not supported in this browser.<br/>Try a recent Chrome / Firefox / Edge."
    );
    return;
  }

  channel = new BroadcastChannel("multi-window-complex-object");

  channel.onmessage = (event) => {
    const msg = event.data;
    if (!msg || typeof msg !== "object") return;
    if (!msg.id || msg.id === myId) return; // ignore our own echoes

    if (msg.type === "hello" || msg.type === "update") {
      peers.set(msg.id, {
        id: msg.id,
        x: msg.x,
        y: msg.y,
        w: msg.w,
        h: msg.h,
        lastSeen: Date.now()
      });

      // when someone says hello, we answer with our own state
      if (msg.type === "hello") {
        broadcastUpdate();
      }
    } else if (msg.type === "goodbye") {
      peers.delete(msg.id);
    }
  };

  // Say hello to others
  broadcastHello();

  // Periodically refresh our bounds & prune stale peers
  setInterval(() => {
    broadcastUpdate();
    prunePeers();
  }, 700);
}

function broadcastHello() {
  if (!channel) return;
  updateSelfPeer();
  const self = peers.get(myId);
  channel.postMessage({
    type: "hello",
    ...self
  });
}

function broadcastUpdate() {
  if (!channel) return;
  updateSelfPeer();
  const self = peers.get(myId);
  channel.postMessage({
    type: "update",
    ...self
  });
}

function broadcastGoodbye() {
  if (!channel) return;
  channel.postMessage({ type: "goodbye", id: myId });
}

function prunePeers() {
  const now = Date.now();
  const maxAge = 5000; // ms
  for (const [id, peer] of peers) {
    if (id === myId) continue;
    if (now - peer.lastSeen > maxAge) {
      peers.delete(id);
    }
  }
}

// ---------- p5 setup & UI ----------

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(RADIANS);
  noiseSeed(1); // deterministic noise across windows
  noFill();

  myId = makeId();
  updateSelfPeer();

  // Info panel
  infoDiv = createDiv("Connecting…");
  infoDiv.position(12, 12);
  infoDiv.style("padding", "8px 10px");
  infoDiv.style("border-radius", "10px");
  infoDiv.style("background", "rgba(5,10,28,0.92)");
  infoDiv.style("color", "#eaf0ff");
  infoDiv.style("font-size", "12px");
  infoDiv.style("border", "1px solid rgba(146,190,255,0.5)");
  infoDiv.style("backdrop-filter", "blur(8px)");
  infoDiv.style("max-width", "260px");

  openBtn = createButton("Open another window");
  openBtn.position(12, 80);
  openBtn.mousePressed(openAnotherWindow);
  openBtn.style("padding", "6px 12px");
  openBtn.style("border-radius", "999px");
  openBtn.style("border", "1px solid rgba(146,190,255,0.8)");
  openBtn.style("background", "radial-gradient(circle at 0 0, #1b2b5d, #050814)");
  openBtn.style("color", "#eaf0ff");
  openBtn.style("font-size", "12px");
  openBtn.style("cursor", "pointer");

  connectChannel();

  window.addEventListener("beforeunload", broadcastGoodbye);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  updateSelfPeer();
  broadcastUpdate();
}

function openAnotherWindow() {
  const w = 600;
  const h = 600;
  const left = (window.screenX || 0) + 40;
  const top = (window.screenY || 0) + 40;

  window.open(
    window.location.href,
    "_blank",
    `width=${w},height=${h},left=${left},top=${top}`
  );
}

// ---------- p5 draw loop ----------

function draw() {
  // Shared time-based angle (same across all windows)
  const t = Date.now() * 0.001;
  const globalAngle = t * 0.4;

  // Build ordered peer list
  updateSelfPeer();
  let list = Array.from(peers.values());
  if (list.length === 0) {
    list = [
      {
        id: myId,
        x: 0,
        y: 0,
        w: window.innerWidth || width,
        h: window.innerHeight || height
      }
    ];
  }
  list.sort((a, b) => a.x - b.x);

  const total = list.length;
  let index = list.findIndex((p) => p.id === myId);
  if (index === -1) index = 0;

  const segAngle = TWO_PI / max(1, total);
  const myStart = segAngle * index + globalAngle * 0.25;
  const myEnd = myStart + segAngle;

  // Draw background + vortex for this segment
  drawBackgroundGradient(index, total);
  drawVortexSegment(globalAngle, myStart, myEnd);
  drawHUD(list, index, total);
}

// ---------- VFX rendering ----------

function drawBackgroundGradient(segIndex, segTotal) {
  // Soft radial gradient influenced by segment index
  const hueBias = map(segIndex, 0, max(1, segTotal - 1), 0.55, 0.95);
  const centerX = width * 0.52;
  const centerY = height * 0.45;

  push();
  colorMode(HSB, 1);
  noFill();
  const maxR = max(width, height) * 1.1;
  for (let r = maxR; r > 0; r -= 10) {
    const u = r / maxR;
    const a = pow(u, 2.0);
    const bright = 0.04 + 0.28 * (1 - a);
    const sat = 0.4 + 0.3 * (1 - a);
    stroke(hueBias, sat, bright, 0.6 * (1 - a));
    strokeWeight(10);
    ellipse(centerX, centerY, r, r);
  }
  pop();
}

function drawVortexSegment(globalAngle, myStart, myEnd) {
  const baseR = Math.min(width, height) * 0.28;

  push();
  translate(width / 2, height / 2);

  // 1) Glowing torus (multiple offset arcs, additive blend)
  blendMode(ADD);
  for (let layer = 0; layer < 4; layer++) {
    const r = baseR * (1.6 + layer * 0.06);
    const thickness = 5 + layer * 2;
    const wobble = sin(globalAngle * 1.3 + layer) * baseR * 0.04;

    strokeWeight(thickness);
    const alpha = 35 + layer * 20;
    // RGB with alpha (default color mode)
    stroke(60 + layer * 25, 150 + layer * 20, 255, alpha);
    noFill();
    arc(0, 0, (r + wobble) * 2, (r + wobble) * 2, myStart, myEnd);
  }

  // 2) Particle ring
  strokeWeight(1);
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const u = i / PARTICLE_COUNT;

    // Angle for this particle around full ring
    const a = u * TWO_PI + globalAngle * 0.75;

    // Only draw if this angle lives inside our segment
    let norm = a;
    while (norm < myStart) norm += TWO_PI;
    while (norm > myEnd) norm -= TWO_PI;
    if (norm < myStart || norm > myEnd) continue;

    // Radial position modulated by noise
    const noiseR = baseR * 0.25;
    const n = noise(
      u * INNER_NOISE_SCALE,
      globalAngle * 0.35 + i * 0.007
    );
    const r = baseR * 1.4 + (n - 0.5) * 2.0 * noiseR;

    const x = cos(a) * r;
    const y = sin(a) * r;

    const flicker = 0.4 + 0.6 * sin(globalAngle * 3 + i * 0.21);
    const alpha = 90 + 80 * flicker;

    stroke(180, 220, 255, alpha);
    fill(140, 210, 255, alpha);
    const s = 1.5 + 2.5 * (1.0 - u);
    ellipse(x, y, s * 2, s * 2);
    noFill();
  }

  // 3) Field lines inside the sector
  noFill();
  for (let j = 0; j < FIELD_LINE_COUNT; j++) {
    const seed = j * 0.5 + floor(globalAngle * 2.0);
    const localStart = lerp(myStart, myEnd, random(0.0, 1.0));
    const length = random(0.2, 0.9) * (myEnd - myStart);
    const localEnd = localStart + length;

    const steps = 28;
    let prevX = null;
    let prevY = null;

    stroke(120, 230, 255, 90);
    strokeWeight(1.2);

    for (let k = 0; k <= steps; k++) {
      const v = k / steps;
      const a = lerp(localStart, localEnd, v);

      const outerNoise =
        noise(
          seed,
          OUTER_NOISE_SCALE * v + globalAngle * 0.25
        ) - 0.5;

      const rInner = baseR * 0.8;
      const rOuter = baseR * 1.15;
      let r = lerp(rInner, rOuter, v);
      r += outerNoise * baseR * 0.18;

      const x = cos(a) * r;
      const y = sin(a) * r;

      if (prevX !== null) {
        line(prevX, prevY, x, y);
      }
      prevX = x;
      prevY = y;
    }
  }

  // 4) Inner nucleus (switch back to normal blend)
  blendMode(BLEND);
  const nucleusR = baseR * 0.55;
  for (let r = nucleusR; r > 0; r -= 6) {
    const u = r / nucleusR;
    const a = pow(u, 1.3);
    const alpha = 18 + 35 * (1 - a);
    stroke(90, 150, 255, alpha);
    noFill();
    ellipse(0, 0, r * 2, r * 2);
  }

  pop();
}

// ---------- HUD / mini-map ----------

function drawHUD(list, index, total) {
  infoDiv.html(
    `<strong>Window ID:</strong> ${myId || "…"}<br>` +
      `<strong>Segment:</strong> ${index + 1} / ${total}<br>` +
      `<strong>Open windows:</strong> ${list.length}`
  );

  push();
  resetMatrix();
  const pad = 12;
  const mapW = 180;
  const mapH = 80;

  translate(width - mapW - pad, height - mapH - pad);

  noFill();
  stroke(80, 110, 170);
  strokeWeight(1);
  rect(0, 0, mapW, mapH, 8);

  if (list.length > 0) {
    const xs = list.map((c) => c.x);
    const ys = list.map((c) => c.y);
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
    const spanX = Math.max(1, maxX - minX);
    const spanY = Math.max(1, maxY - minY);

    list.forEach((c) => {
      const nx = (c.x - minX) / spanX;
      const ny = (c.y - minY) / spanY;

      const px = 6 + nx * (mapW - 12);
      const py = 6 + ny * (mapH - 12);

      const isMe = c.id === myId;
      noStroke();
      fill(isMe ? color(80, 220, 255) : color(160, 180, 220));

      const r = isMe ? 8 : 6;
      ellipse(px, py, r, r);

      if (isMe) {
        noFill();
        stroke(80, 220, 255);
        strokeWeight(1);
        ellipse(px, py, r + 6, r + 6);
      }
    });
  }

  pop();
}
